insert into gethired_private.categories(id,name,description,color,bg,phases) values ('687a8bce-ec6b-4dbf-89fa-097c02d18f2f','Web Development','HTML, CSS, JavaScript, React, REST APIs, databases','#0073ff','#dfe9ff','[{"id":"intro","label":"Introduction","shortLabel":"Intro","types":["Introduction"],"count":1},{"id":"situational","label":"Situational","shortLabel":"Situational","types":["Situational"],"count":1},{"id":"technical","label":"Technical","shortLabel":"Technical","types":["Technical"],"count":2},{"id":"coding","label":"Practical Challenge","shortLabel":"Practical","types":["Coding"],"count":1},{"id":"your-questions","label":"Your Questions","shortLabel":"Q&A","types":["Candidate Questions"],"count":1}]') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('ace310cf-979d-40d9-8ba9-7fd65381598e','687a8bce-ec6b-4dbf-89fa-097c02d18f2f','Explain the difference between `==` and `===` in JavaScript. Give a concrete example of when each should — and should not — be used.','Technical','Think about type coercion vs. strict equality comparison.','A strong answer clearly distinguishes type coercion (==) from strict comparison (===), provides concrete examples (0 == false is true, but 0 === false is false), and recommends === as the default practice to avoid unexpected bugs. Mentioning common gotchas like null == undefined earns extra points.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('e586ef56-d38e-4fc9-8857-6d1a0ff7ebb7','687a8bce-ec6b-4dbf-89fa-097c02d18f2f','What is the Virtual DOM in React? Explain how it works and why it improves performance over directly manipulating the real DOM.','Technical','Explain the diffing algorithm and reconciliation process.','Strong answers describe the Virtual DOM as an in-memory UI representation, explain React''s reconciliation/diffing algorithm, and contrast it with expensive real DOM operations. Mention that React only updates the minimal changed parts, and optionally discuss React Fiber''s incremental rendering.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('f620c951-2ce6-4dad-870a-b923826babe9','687a8bce-ec6b-4dbf-89fa-097c02d18f2f','Describe a challenging front-end bug you encountered in a project. How did you identify the root cause and resolve it?','Behavioral','Use the STAR method: Situation, Task, Action, Result.','Strong responses follow the STAR method, show systematic debugging (DevTools, console logs, isolating components), and demonstrate what you learned. Quantifying impact (e.g., ''fixed a race condition causing 20% of form submissions to fail'') and mentioning tools used shows technical depth.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('671aff68-2a49-454e-8dab-74ced12dcace','687a8bce-ec6b-4dbf-89fa-097c02d18f2f','Please introduce yourself, your academic background, a project you are proud of, and your interest in Web Development.','Introduction','Keep your introduction focused and specific.','Look for a clear background, a concrete example and motivation for this field.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('a97fa33c-8c5d-42db-8012-76cc6f94148a','687a8bce-ec6b-4dbf-89fa-097c02d18f2f','Describe a difficult problem you solved in a Web Development context. What did you do and learn?','Situational','Use Situation, Task, Action and Result.','Look for a specific problem, personal actions, a concrete result and reflection.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('d4d01d59-8ec0-4556-8473-bd27ac7e1dab','687a8bce-ec6b-4dbf-89fa-097c02d18f2f','What would you like to ask about the role, team, mentoring or daily work?','Candidate Questions','Ask specific questions about the placement.','Look for curiosity and thoughtful questions about the role and learning opportunities.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('2b4b3156-bfa0-4ea0-89a8-de7587541914','687a8bce-ec6b-4dbf-89fa-097c02d18f2f','Implement a debounce function in JavaScript from scratch. Then show how you would use it to delay an API call triggered by a search input field. Explain why debouncing matters in this context.','Coding','A debounce delays execution until N ms have passed since the last call. Use setTimeout and clearTimeout. The returned function should preserve `this` and spread arguments.','A complete answer implements the core debounce (closure over a timer, clearTimeout on each new call, setTimeout with the provided delay), shows its usage on an input''s onChange handler, and explains the user-experience rationale (avoids an API request on every keystroke). Bonus points for handling edge cases like immediate invocation on the first call, or noting that lodash/debounce exists for production use. Using `function` vs arrow function to preserve `this` context is a common gotcha worth mentioning.') on conflict (id) do nothing;
insert into gethired_private.categories(id,name,description,color,bg,phases) values ('66610e35-8728-49a1-88d7-6c373cbff6ce','Data Science & Analytics','Python, SQL, Machine Learning, data visualization','#7c3aed','#ede9fe','[{"id":"intro","label":"Introduction","shortLabel":"Intro","types":["Introduction"],"count":1},{"id":"situational","label":"Situational","shortLabel":"Situational","types":["Situational"],"count":1},{"id":"technical","label":"Technical","shortLabel":"Technical","types":["Technical"],"count":2},{"id":"coding","label":"Practical Challenge","shortLabel":"Practical","types":["Coding"],"count":1},{"id":"your-questions","label":"Your Questions","shortLabel":"Q&A","types":["Candidate Questions"],"count":1}]') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('36bcb338-a63b-4a59-8d73-5de53386d7ed','66610e35-8728-49a1-88d7-6c373cbff6ce','What is the difference between supervised and unsupervised learning? Give a real-world example of each relevant to the Philippine context.','Technical','Supervised uses labeled data; unsupervised finds patterns in unlabeled data.','A comprehensive answer explains labeled vs. unlabeled datasets, correctly categorizes algorithms (classification/regression vs. clustering/dimensionality reduction), and gives relevant local examples (e.g., fraud detection in GCash/Maya for supervised; customer segmentation for unsupervised).') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('75596c37-b278-4bf5-84ab-b58aaea06bd7','66610e35-8728-49a1-88d7-6c373cbff6ce','Your dataset has 35% missing values in a critical feature column. Walk through your complete decision-making process for handling this.','Technical','Consider imputation strategies, dropping, and model-based approaches.','Strong answers discuss multiple strategies (mean/median imputation, KNN imputation, MICE, creating a missingness indicator) and explain that the right approach depends on WHY data is missing (MCAR, MAR, MNAR). Mentioning domain knowledge as a factor shows practical experience.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('a118ac6d-17a6-4863-848e-4f72a57c8854','66610e35-8728-49a1-88d7-6c373cbff6ce','Tell me about a time you presented data findings to a non-technical audience. How did you make the insights clear and actionable?','Behavioral','Focus on storytelling, visualization choices, and avoiding jargon.','Effective answers lead with business insights (not methodology), use visuals over raw tables, employ analogies for complex concepts, and confirm understanding with follow-up questions. Mentioning specific tools like Tableau, Power BI, or even simple Google Slides strengthens the answer.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('ceab0e91-2c56-40ef-845c-6eda63c9775d','66610e35-8728-49a1-88d7-6c373cbff6ce','Please introduce yourself, your academic background, a project you are proud of, and your interest in Data Science & Analytics.','Introduction','Keep your introduction focused and specific.','Look for a clear background, a concrete example and motivation for this field.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('26df8359-d7a1-4fb8-84d2-255ec10ba450','66610e35-8728-49a1-88d7-6c373cbff6ce','Describe a difficult problem you solved in a Data Science & Analytics context. What did you do and learn?','Situational','Use Situation, Task, Action and Result.','Look for a specific problem, personal actions, a concrete result and reflection.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('3570508e-0e00-4101-8cb2-ab069d69027c','66610e35-8728-49a1-88d7-6c373cbff6ce','What would you like to ask about the role, team, mentoring or daily work?','Candidate Questions','Ask specific questions about the placement.','Look for curiosity and thoughtful questions about the role and learning opportunities.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('d749122e-34dc-4b83-8292-1d76f447a127','66610e35-8728-49a1-88d7-6c373cbff6ce','Given a sales DataFrame with columns [date, product, region, revenue], write Python/pandas code to: (1) find the top 3 products by total revenue in Q1 of the current year, and (2) calculate the month-over-month revenue growth rate for each region. Show your code and briefly explain each step.','Coding','Use pd.to_datetime for date parsing, .groupby() + .sum() for aggregation, .pct_change() for growth rates, and .nlargest() for ranking. Filter Q1 with .dt.quarter == 1.','A solid answer parses the date column correctly, filters for Q1 using .dt.quarter, groups by product, sums revenue, and uses .nlargest(3). For MoM growth, grouping by [region, month] then applying .pct_change() on the sorted series is the key step. Formatting the output clearly (reset_index, round percentages) shows production-quality thinking. Mentioning .fillna(0) for missing months and potential division-by-zero handling earns extra credit.') on conflict (id) do nothing;
insert into gethired_private.categories(id,name,description,color,bg,phases) values ('a2300a72-1092-4088-88d5-06d5d632f483','Cybersecurity','Network security, ethical hacking, risk assessment','#dc2626','#fee2e2','[{"id":"intro","label":"Introduction","shortLabel":"Intro","types":["Introduction"],"count":1},{"id":"situational","label":"Situational","shortLabel":"Situational","types":["Situational"],"count":1},{"id":"technical","label":"Technical","shortLabel":"Technical","types":["Technical"],"count":2},{"id":"your-questions","label":"Your Questions","shortLabel":"Q&A","types":["Candidate Questions"],"count":1}]') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('da484c1c-26c4-4417-8054-cbb831937c7f','a2300a72-1092-4088-88d5-06d5d632f483','Explain the difference between symmetric and asymmetric encryption. When would you use each, and what are the trade-offs?','Technical','Consider key management, speed, and use cases like HTTPS and file encryption.','Strong answers explain symmetric (same key, faster, key distribution problem) vs. asymmetric (public/private pair, slower, solves key distribution). Excellent answers mention hybrid approaches used in TLS and give concrete algorithm examples (AES-256, RSA-2048). Mentioning performance implications earns bonus points.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('10c258ad-e142-4400-80ce-ab1e3eb58f8c','a2300a72-1092-4088-88d5-06d5d632f483','What is a SQL injection attack? Show an example of vulnerable code and explain at least three prevention techniques.','Technical','Think about parameterized queries, input validation, and least-privilege principles.','Comprehensive answers show a real vulnerable query, demonstrate the exploit (e.g., entering '' OR 1=1 --), and clearly explain mitigations: parameterized queries/prepared statements, input validation and sanitization, least-privilege DB accounts, and Web Application Firewalls (WAFs).') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('a099c391-fd09-4836-8503-ccd3775e6788','a2300a72-1092-4088-88d5-06d5d632f483','During your OJT, you discover a critical zero-day vulnerability in a production system. No senior is immediately available. What do you do?','Situational','Think about responsible disclosure, escalation, containment, and documentation.','Outstanding answers follow responsible disclosure: thoroughly document the vulnerability (screenshots, reproduction steps), escalate through proper channels even after hours, avoid publicizing it externally, and recommend temporary mitigations without taking drastic unilateral action. Shows ethical judgment and professionalism.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('798b1347-fa55-4ca4-8f69-64ee77fce95c','a2300a72-1092-4088-88d5-06d5d632f483','Please introduce yourself, your academic background, a project you are proud of, and your interest in Cybersecurity.','Introduction','Keep your introduction focused and specific.','Look for a clear background, a concrete example and motivation for this field.') on conflict (id) do nothing;
