insert into gethired_private.categories(id,name,description,color,bg,phases) values ('11f236cd-a3b7-4282-8f4d-213f33a23028','BPO & Customer Service','Communication, problem solving, customer relations','#059669','#d1fae5','[{"id":"intro","label":"Introduction","shortLabel":"Intro","types":["Introduction"],"count":1},{"id":"situational","label":"Situational","shortLabel":"Situational","types":["Situational"],"count":1},{"id":"behavioral","label":"Behavioral","shortLabel":"Behavioral","types":["Behavioral","Motivational"],"count":2},{"id":"your-questions","label":"Your Questions","shortLabel":"Q&A","types":["Candidate Questions"],"count":1}]') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('7b74b97e-30cc-4ab7-86f2-0eaf93e847bf','11f236cd-a3b7-4282-8f4d-213f33a23028','A customer calls furious about a billing error they''ve experienced three times this month. How do you handle the interaction?','Situational','Lead with empathy, take ownership, and provide a clear resolution path.','Strong answers demonstrate the HEARD technique (Hear, Empathize, Apologize, Resolve, Diagnose), avoid defensive language, take personal ownership (''I will personally ensure this is fixed today''), provide a concrete resolution timeline, and mention follow-up. Proposing compensation or escalation when warranted shows customer-first thinking.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('b8fa475e-de53-4517-84b9-a77e07d9b2b3','11f236cd-a3b7-4282-8f4d-213f33a23028','How do you maintain focus and accuracy during a high-volume shift with back-to-back calls or tickets?','Behavioral','Discuss tools, prioritization strategies, and how you handle burnout.','Effective answers discuss concrete strategies: batch processing similar tickets, using keyboard shortcuts/macros, structured note-taking between calls, prioritizing by urgency/impact, and sustainable self-care (short mental resets, staying hydrated). Shows awareness of sustainable productivity over time.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('a5720a05-d3ad-49ce-8f9b-e7a97ea0dbbf','11f236cd-a3b7-4282-8f4d-213f33a23028','What does excellent customer service mean to you? Give a specific example of when you went above and beyond for someone.','Behavioral','Be specific and personal. Show you care about outcomes, not just scripts.','Great answers define excellence as making customers feel heard and genuinely valued — not just resolving the ticket. Specific examples with measurable outcomes are far more powerful than generalizations. Tying your philosophy back to business value (retention, NPS, word-of-mouth) shows business acumen.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('10d6a640-3210-475d-8a95-c2fe31b74658','11f236cd-a3b7-4282-8f4d-213f33a23028','Please introduce yourself, your academic background, a project you are proud of, and your interest in BPO & Customer Service.','Introduction','Keep your introduction focused and specific.','Look for a clear background, a concrete example and motivation for this field.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('e2bfd831-bbac-461d-88ea-f23e5ce3f2cc','11f236cd-a3b7-4282-8f4d-213f33a23028','Describe a difficult problem you solved in a BPO & Customer Service context. What did you do and learn?','Situational','Use Situation, Task, Action and Result.','Look for a specific problem, personal actions, a concrete result and reflection.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('3c556928-0d10-451d-820a-8838c1c72cc0','11f236cd-a3b7-4282-8f4d-213f33a23028','What would you like to ask about the role, team, mentoring or daily work?','Candidate Questions','Ask specific questions about the placement.','Look for curiosity and thoughtful questions about the role and learning opportunities.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('40914b1e-11e6-4734-86b1-e7281d74ff39','11f236cd-a3b7-4282-8f4d-213f33a23028','A customer contacts you via chat saying their internet service has been down for 6 hours. They are working from home and have already missed two important meetings. They are very upset and have threatened to cancel their account. Write your full chat response: (1) your opening message, (2) how you troubleshoot with them, (3) how you escalate if needed, and (4) your closing message. Use realistic customer service language.','Situational','Lead with empathy before troubleshooting. Acknowledge the business impact specifically. Offer a concrete resolution timeline. Use ''I'' statements to take ownership.','A strong response opens with genuine empathy acknowledging the missed meetings (not just the outage), introduces yourself by name to personalize the interaction, and uses ''I'' language to take ownership (''I will personally make sure this is resolved''). Troubleshooting should be structured (check account status → basic modem reset → line check → technical escalation) with clear communication at each step. Escalation language should empower rather than deflect (''I''m bringing in our senior technical team right now''). The closing should confirm resolution, offer compensation if applicable, and thank them for their patience.') on conflict (id) do nothing;
insert into gethired_private.categories(id,name,description,color,bg,phases) values ('b4fa8a85-6a6f-4091-81ab-e70a32ac982e','Behavioral / HR Interview','STAR method, soft skills, situational judgment','#d97706','#fef3c7','[{"id":"intro","label":"Introduction","shortLabel":"Intro","types":["Introduction"],"count":1},{"id":"situational","label":"Situational","shortLabel":"Situational","types":["Situational"],"count":1},{"id":"behavioral","label":"Behavioral","shortLabel":"Behavioral","types":["Behavioral","Motivational"],"count":2},{"id":"your-questions","label":"Your Questions","shortLabel":"Q&A","types":["Candidate Questions"],"count":1}]') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('9acd1cd6-46ce-45aa-8ddc-1098db8d647b','b4fa8a85-6a6f-4091-81ab-e70a32ac982e','Tell me about a time you had to work with a difficult team member on a group project. How did you navigate it?','Behavioral','Focus on what YOU did, not what the other person did wrong. Use STAR.','Strong STAR responses highlight the candidate''s own behavior (empathy, direct communication, compromise) without blaming the other party. Excellent answers show maturity: recognizing different working styles, finding common ground, and ending with a positive outcome for the team. Shows emotional intelligence.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('e6366821-57da-4cf7-8459-e51f3a2b9eba','b4fa8a85-6a6f-4091-81ab-e70a32ac982e','Describe a situation where you had to quickly learn a new technology or tool under time pressure. What was your approach?','Behavioral','Show your learning process: resources, practice, mentorship, and validation.','Strong answers show a structured learning approach: official documentation, hands-on mini-projects, asking mentors for feedback, and iterating. Demonstrates growth mindset and resourcefulness. Bonus: tie the new skill to a concrete outcome that benefited the team or project.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('f98fba9f-9fb7-4aea-8f41-993d46218930','b4fa8a85-6a6f-4091-81ab-e70a32ac982e','Where do you see yourself professionally in 3 years? How does completing your OJT at this company fit into that plan?','Motivational','Be specific, show knowledge of the company, and connect your goals to what they offer.','Compelling answers name a specific career direction (not just ''I want to be a developer''), demonstrate genuine knowledge of what the company does and the industry it''s in, and explain why this particular OJT is a strategic step in their plan. Authentic enthusiasm beats rehearsed generic ambition every time.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('c715969a-88eb-43fc-801d-f4bf5a7967f8','b4fa8a85-6a6f-4091-81ab-e70a32ac982e','Please introduce yourself, your academic background, a project you are proud of, and your interest in Behavioral / HR Interview.','Introduction','Keep your introduction focused and specific.','Look for a clear background, a concrete example and motivation for this field.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('83e58df3-30da-4613-8b54-b9573606d805','b4fa8a85-6a6f-4091-81ab-e70a32ac982e','Describe a difficult problem you solved in a Behavioral / HR Interview context. What did you do and learn?','Situational','Use Situation, Task, Action and Result.','Look for a specific problem, personal actions, a concrete result and reflection.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('83574710-0bf2-4a36-8c35-8ac069834cba','b4fa8a85-6a6f-4091-81ab-e70a32ac982e','What would you like to ask about the role, team, mentoring or daily work?','Candidate Questions','Ask specific questions about the placement.','Look for curiosity and thoughtful questions about the role and learning opportunities.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('7b8036b6-6a6a-47cc-8eb4-f717f5483655','b4fa8a85-6a6f-4091-81ab-e70a32ac982e','You are interviewing for your OJT placement. The interviewer says: ''Walk me through a specific project or academic experience where things did not go as planned. What went wrong, what did you do about it, and what would you do differently today?'' Write your full answer as you would actually say it in a real interview.','Behavioral','Use STAR. Choose a real, specific example. Be honest about what went wrong — interviewers respect self-awareness. Focus on what YOU personally did, not what the team did. End with a concrete lesson.','A compelling answer chooses a specific story (not vague ''we had a group project'') and is honest about the failure without excessive self-criticism. The STAR structure keeps it focused: Situation (context), Task (your role), Action (what you specifically did to address it), Result (outcome and learning). Strong answers name a concrete lesson that you have since applied — this shows growth mindset. Avoid stories where external factors (bad teammates, unclear instructions) are entirely to blame for the failure. Interviewers want to see that you take ownership.') on conflict (id) do nothing;
insert into gethired_private.categories(id,name,description,color,bg,phases) values ('1defaf26-c17a-4b70-8585-4f25d2a7e5b4','Mobile Development','React Native, Flutter, iOS, Android, app architecture','#0891b2','#e0f7fa','[{"id":"intro","label":"Introduction","shortLabel":"Intro","types":["Introduction"],"count":1},{"id":"situational","label":"Situational","shortLabel":"Situational","types":["Situational"],"count":1},{"id":"technical","label":"Technical","shortLabel":"Technical","types":["Technical"],"count":2},{"id":"coding","label":"Practical Challenge","shortLabel":"Practical","types":["Coding"],"count":1},{"id":"your-questions","label":"Your Questions","shortLabel":"Q&A","types":["Candidate Questions"],"count":1}]') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('58a90664-3f94-402e-8dd9-b882b4ca837f','1defaf26-c17a-4b70-8585-4f25d2a7e5b4','Explain the key architectural differences between React Native and Flutter. What factors would influence your choice between them for a new project?','Technical','Think about language, rendering approach, ecosystem, and performance trade-offs.','Strong answers distinguish React Native (JavaScript bridge, native components) from Flutter (Dart, custom rendering engine). Mentioning trade-offs — RN''s larger ecosystem vs. Flutter''s consistent UI across platforms, or Dart''s learning curve vs. JS familiarity — shows depth. Noting company stack, team skills, and platform targets as decision factors earns extra credit.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('829648d8-f98a-4438-8851-882f214b994c','1defaf26-c17a-4b70-8585-4f25d2a7e5b4','What is state management in mobile applications, and why does it matter? Compare at least two state management solutions and explain when you''d use each.','Technical','Cover local vs. global state. Think about Redux, Zustand, Provider, Bloc, or Context API.','A solid answer explains why uncontrolled state causes bugs and UI inconsistency, then compares approaches: local state (useState/setState) for isolated components, Context API or Provider for moderate shared state, Redux/Bloc/Zustand for complex global state with many consumers. Mentioning boilerplate trade-offs and when NOT to use a heavy state manager shows practical judgment.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('fd672f2a-1e9d-4212-8bb8-8fbff7f55263','1defaf26-c17a-4b70-8585-4f25d2a7e5b4','Describe a mobile app you built or significantly contributed to. Walk through a specific technical challenge you encountered and how you resolved it.','Behavioral','Use STAR. Focus on technical depth — what broke, how you diagnosed it, what you shipped.','Strong responses detail a real problem — memory leaks, slow FlatList rendering, API race conditions, platform-specific bugs — and walk through the debugging and resolution process. Mentioning tools (Flipper, Xcode Instruments, Android Profiler) and measurable outcomes (startup time, crash rate) elevates the answer significantly.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('6166fc5a-7d1a-475d-8ded-de290f1a6a0c','1defaf26-c17a-4b70-8585-4f25d2a7e5b4','Please introduce yourself, your academic background, a project you are proud of, and your interest in Mobile Development.','Introduction','Keep your introduction focused and specific.','Look for a clear background, a concrete example and motivation for this field.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('d82c182a-a2e3-4256-8022-a853de6a95d6','1defaf26-c17a-4b70-8585-4f25d2a7e5b4','Describe a difficult problem you solved in a Mobile Development context. What did you do and learn?','Situational','Use Situation, Task, Action and Result.','Look for a specific problem, personal actions, a concrete result and reflection.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('c19e56b5-e289-4cc3-8221-830182f8b964','1defaf26-c17a-4b70-8585-4f25d2a7e5b4','What would you like to ask about the role, team, mentoring or daily work?','Candidate Questions','Ask specific questions about the placement.','Look for curiosity and thoughtful questions about the role and learning opportunities.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('82ae9dc0-5c15-4245-8767-2d24a4f94788','1defaf26-c17a-4b70-8585-4f25d2a7e5b4','Build a React Native component called ProductList that: fetches a list of products from a REST API (https://api.example.com/products), shows a loading spinner while fetching, handles and displays API errors gracefully, and renders the results in a FlatList with product name and price. Write the full component code.','Coding','Use useEffect + useState (or useReducer) for async state. Structure state as { data, loading, error }. Use ActivityIndicator for loading. FlatList requires keyExtractor and renderItem.','A strong implementation manages three states (loading, error, data) — not just the happy path. Using a try/catch inside useEffect, setting loading to false in a finally block, and showing meaningful error messages (not just console.log) demonstrates production awareness. Passing keyExtractor as a string key (not index) and using memo or useCallback on renderItem for performance shows depth. Bonus: adding a retry button on error state.') on conflict (id) do nothing;
insert into gethired_private.categories(id,name,description,color,bg,phases) values ('bc132195-e7ed-48a3-8611-c5e5153e45dd','Cloud & DevOps','AWS, Azure, GCP, Docker, Kubernetes, CI/CD pipelines','#0369a1','#e0f2fe','[{"id":"intro","label":"Introduction","shortLabel":"Intro","types":["Introduction"],"count":1},{"id":"situational","label":"Situational","shortLabel":"Situational","types":["Situational"],"count":1},{"id":"technical","label":"Technical","shortLabel":"Technical","types":["Technical"],"count":2},{"id":"your-questions","label":"Your Questions","shortLabel":"Q&A","types":["Candidate Questions"],"count":1}]') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('acc24e1f-38de-4f1e-8c69-ae0bff22464a','bc132195-e7ed-48a3-8611-c5e5153e45dd','Explain the difference between IaaS, PaaS, and SaaS. Give a real-world example of each, and describe which model is most appropriate for a startup deploying a web API.','Technical','Think about the responsibility model: who manages what at each layer.','A thorough answer clearly defines each model (IaaS: raw infra — AWS EC2; PaaS: managed platform — Heroku/GCP App Engine; SaaS: ready-to-use software — Salesforce/Gmail) and explains the shared-responsibility boundary. For the startup scenario, recommending PaaS or a managed container service (GCP Cloud Run, AWS ECS) with justification — no infra management overhead — shows practical cloud judgment.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('e3af37d9-fa46-41ff-8be9-86b5f480c046','bc132195-e7ed-48a3-8611-c5e5153e45dd','What is a CI/CD pipeline? Describe the typical stages, explain what happens at each, and name the tools you''ve used or studied.','Technical','Cover source → build → test → artifact → deploy → monitor. Mention at least one tool per stage.','Strong answers walk through: commit triggers (GitHub Actions, GitLab CI, Jenkins), build stage (Docker image creation), automated test suite (unit, integration), artifact storage (container registry, S3), deployment (rolling update, blue-green, canary), and monitoring/rollback strategy. Mentioning environment separation (dev/staging/prod) and IaC tools (Terraform, Ansible) shows senior awareness.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('c2f7a3e9-a2b3-48ca-855d-3865a9e10cda','bc132195-e7ed-48a3-8611-c5e5153e45dd','You deploy a new container image to production and the service immediately starts returning 500 errors. Walk through your incident response process step by step.','Situational','Think: detect → contain → diagnose → fix → post-mortem.','Excellent answers follow an incident response pattern: check monitoring dashboards/alerts first, immediately roll back to the last known-good image to restore service, then diagnose in staging (logs, diff between images, health checks). Mentioning communication (stakeholder updates), blameless post-mortems, and adding a regression test demonstrates SRE maturity beyond just ''fix the bug.''') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('2d6448a7-e9a8-4ac8-823e-acd663fd5802','bc132195-e7ed-48a3-8611-c5e5153e45dd','Please introduce yourself, your academic background, a project you are proud of, and your interest in Cloud & DevOps.','Introduction','Keep your introduction focused and specific.','Look for a clear background, a concrete example and motivation for this field.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('b395756e-088f-47a5-8039-40ef25579353','bc132195-e7ed-48a3-8611-c5e5153e45dd','Describe a difficult problem you solved in a Cloud & DevOps context. What did you do and learn?','Situational','Use Situation, Task, Action and Result.','Look for a specific problem, personal actions, a concrete result and reflection.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('38d02a3e-d0d3-4975-82ad-67969efd2e31','bc132195-e7ed-48a3-8611-c5e5153e45dd','What would you like to ask about the role, team, mentoring or daily work?','Candidate Questions','Ask specific questions about the placement.','Look for curiosity and thoughtful questions about the role and learning opportunities.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('5931944d-9fa5-477e-88d1-3067166931f8','bc132195-e7ed-48a3-8611-c5e5153e45dd','Write a production-ready multi-stage Dockerfile for a Node.js Express API. The build stage should install all dependencies and compile TypeScript. The production stage should only contain the compiled output and production dependencies. Also write a basic GitHub Actions CI workflow that builds and pushes the image to a container registry on push to main.','Coding','Use FROM node:18-alpine AS builder for the build stage. Copy only package*.json first for layer caching. Use --only=production in the final stage. The GH Actions workflow needs checkout, docker/setup-buildx-action, and docker/build-push-action.','A complete Dockerfile uses multi-stage builds to keep the production image small (copying only /dist and running npm ci --only=production). Correct layer ordering (copy package.json → npm install → copy source) is critical for caching. The CI workflow should use docker/login-action for registry auth, build-push-action with tags, and ideally run tests before the build step. Using COPY --chown=node:node and switching to a non-root USER in the final stage demonstrates security awareness.') on conflict (id) do nothing;
insert into gethired_private.categories(id,name,description,color,bg,phases) values ('868e44f6-c8af-4ae8-8fff-05cb63307e1b','UI/UX Design','Figma, user research, prototyping, usability testing','#be185d','#fce7f3','[{"id":"intro","label":"Introduction","shortLabel":"Intro","types":["Introduction"],"count":1},{"id":"situational","label":"Situational","shortLabel":"Situational","types":["Situational"],"count":1},{"id":"technical","label":"Technical","shortLabel":"Technical","types":["Technical"],"count":2},{"id":"coding","label":"Practical Challenge","shortLabel":"Practical","types":["Design Challenge"],"count":1},{"id":"your-questions","label":"Your Questions","shortLabel":"Q&A","types":["Candidate Questions"],"count":1}]') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('31e634ca-4957-416d-8090-f0bb83745170','868e44f6-c8af-4ae8-8fff-05cb63307e1b','Walk me through your end-to-end design process when starting a project from a blank slate. What artifacts do you produce at each stage?','Technical','Cover research → define → ideate → prototype → test → hand-off.','Strong answers follow a structured process: discovery (user interviews, competitive analysis), define (personas, journey maps, problem statement), ideate (sketches, crazy-8s), prototype (low-fi wireframes → high-fi Figma), test (usability sessions, heatmaps), hand-off (design tokens, component specs, developer notes). Mentioning iteration loops and how you incorporate feedback shows real UX maturity.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('872a6557-2f54-4db6-84ca-2a28fe46231d','868e44f6-c8af-4ae8-8fff-05cb63307e1b','What is the difference between usability testing and A/B testing? When is each appropriate, and what metrics do you use to evaluate success?','Technical','Think: qualitative insight vs. quantitative comparison. Sample size matters too.','Usability testing reveals WHY users struggle (qualitative, small sample, moderated sessions, think-aloud protocol). A/B testing reveals WHICH variant performs better (quantitative, large sample, statistical significance required). Using usability testing early to discover problems and A/B testing later to validate solutions is the correct order. Metrics: task completion rate, time-on-task, SUS score (usability); CTR, conversion rate, bounce rate (A/B).') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('67703690-b940-4fee-88ba-f699021267ce','868e44f6-c8af-4ae8-8fff-05cb63307e1b','Tell me about a design decision you made that was challenged by a developer or stakeholder. How did you defend or adapt your position?','Behavioral','Show that you can balance user advocacy with engineering constraints and business goals.','Great answers show collaboration over ego: the candidate clearly explains the user rationale behind their design, actively listens to the constraint (technical feasibility, timeline, cost), and finds a middle ground that preserves the core user goal. Mentioning user research data or usability findings as the anchor for your argument — rather than personal preference — shows professional design advocacy.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('3219ce3b-2f9f-4259-8b10-83c4a07c4d71','868e44f6-c8af-4ae8-8fff-05cb63307e1b','Please introduce yourself, your academic background, a project you are proud of, and your interest in UI/UX Design.','Introduction','Keep your introduction focused and specific.','Look for a clear background, a concrete example and motivation for this field.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('15a88c79-2fa4-4ff5-82c0-c44aeeb906ea','868e44f6-c8af-4ae8-8fff-05cb63307e1b','Describe a difficult problem you solved in a UI/UX Design context. What did you do and learn?','Situational','Use Situation, Task, Action and Result.','Look for a specific problem, personal actions, a concrete result and reflection.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('85f0fbb0-762b-402f-8262-3a5a31bfe653','868e44f6-c8af-4ae8-8fff-05cb63307e1b','What would you like to ask about the role, team, mentoring or daily work?','Candidate Questions','Ask specific questions about the placement.','Look for curiosity and thoughtful questions about the role and learning opportunities.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('b6ee4844-0819-4e2d-8f48-c04bd2b1fb49','868e44f6-c8af-4ae8-8fff-05cb63307e1b','You are redesigning the checkout flow for a Philippine e-commerce mobile app. Analytics show 68% of users abandon the cart specifically at the payment step. Describe your full UX research and design process, identify likely causes of abandonment, and sketch (in text) the key screens of your proposed redesign. What metrics would you use to measure success?','Design Challenge','Start with research (user interviews, session recordings, heatmaps). Common causes: unexpected fees, too many form fields, trust signals missing, no preferred payment method. Philippine context: GCash/Maya, COD preference.','A strong answer identifies research methods before jumping to solutions (session recordings, exit surveys, checkout funnel analytics). Root causes commonly include hidden shipping fees, forced account creation, limited local payment options (no GCash/Maya/COD), and lack of trust signals (padlock, security badges). The redesign should address each: show total price early, offer guest checkout, add GCash/Maya, display trust signals prominently. Success metrics: checkout completion rate, payment step abandonment rate, time-on-payment-page, and post-launch NPS.') on conflict (id) do nothing;
insert into gethired_private.categories(id,name,description,color,bg,phases) values ('ec2acb08-cb56-4e09-8c78-babdf1f19024','Database Administration','SQL, PostgreSQL, MySQL, MongoDB, normalization, query optimization','#b45309','#fef3c7','[{"id":"intro","label":"Introduction","shortLabel":"Intro","types":["Introduction"],"count":1},{"id":"situational","label":"Situational","shortLabel":"Situational","types":["Situational"],"count":1},{"id":"technical","label":"Technical","shortLabel":"Technical","types":["Technical"],"count":2},{"id":"coding","label":"Practical Challenge","shortLabel":"Practical","types":["Coding"],"count":1},{"id":"your-questions","label":"Your Questions","shortLabel":"Q&A","types":["Candidate Questions"],"count":1}]') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('f5a72751-4608-4e0f-80ef-d26d0cc20d61','ec2acb08-cb56-4e09-8c78-babdf1f19024','Explain the difference between INNER JOIN, LEFT JOIN, RIGHT JOIN, and FULL OUTER JOIN. For each, describe a scenario where it''s the correct choice.','Technical','Think in terms of which rows are preserved when there is no match on the other side.','Solid answers pair each join type with a concrete scenario: INNER JOIN (orders with matching customers only), LEFT JOIN (all customers, including those with no orders — to find inactive users), RIGHT JOIN (rarely preferred; same as LEFT with tables swapped), FULL OUTER JOIN (all records from both tables — for reconciliation or merge reports). Drawing the Venn diagram in words earns extra points.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('6053f50a-504c-4ff3-8dd6-3054fa1c07a7','ec2acb08-cb56-4e09-8c78-babdf1f19024','What is database normalization? Explain 1NF, 2NF, and 3NF with a practical example, and describe when you might intentionally denormalize.','Technical','Use a concrete table example. Denormalization has legitimate use cases — name one.','A complete answer walks through: 1NF (atomic values, no repeating groups), 2NF (no partial dependencies on composite PK), 3NF (no transitive dependencies). Using a real example — like an Orders table — to show each violation and its fix is ideal. For denormalization: reporting databases, read-heavy workloads, and OLAP warehouses are valid cases. Mentioning performance as the trade-off against data integrity demonstrates balance.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('1cfdcc11-3505-42c1-8115-3fb5bd2d896c','ec2acb08-cb56-4e09-8c78-babdf1f19024','A SQL query on a table with 5 million rows is taking 30 seconds. Walk through your complete process for diagnosing and optimizing it.','Technical','Start with EXPLAIN/EXPLAIN ANALYZE, then think indexes, joins, SELECT *, and query rewriting.','Strong answers follow a systematic approach: run EXPLAIN/EXPLAIN ANALYZE to read the query plan, identify full table scans or nested loops, check if appropriate indexes exist (and if the query is using them), review SELECT * usage, look for N+1 patterns in application code, consider pagination. Advanced answers mention covering indexes, query rewriting, materialized views, or partitioning for very large tables.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('19b6b948-c121-4979-8dd7-a6d6bdc47c16','ec2acb08-cb56-4e09-8c78-babdf1f19024','Please introduce yourself, your academic background, a project you are proud of, and your interest in Database Administration.','Introduction','Keep your introduction focused and specific.','Look for a clear background, a concrete example and motivation for this field.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('543ddbcb-608d-420d-84f4-c02dbd72b9fb','ec2acb08-cb56-4e09-8c78-babdf1f19024','Describe a difficult problem you solved in a Database Administration context. What did you do and learn?','Situational','Use Situation, Task, Action and Result.','Look for a specific problem, personal actions, a concrete result and reflection.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('8a623eb9-6c79-4913-8258-01dfdedb6c72','ec2acb08-cb56-4e09-8c78-babdf1f19024','What would you like to ask about the role, team, mentoring or daily work?','Candidate Questions','Ask specific questions about the placement.','Look for curiosity and thoughtful questions about the role and learning opportunities.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('27b6173d-94af-4a5d-86e4-6548031aa814','ec2acb08-cb56-4e09-8c78-babdf1f19024','Given a company database with tables: employees(id, name, dept_id, salary, hire_date) and departments(id, name, manager_id), write SQL queries to: (1) find the top 3 highest-paid employees per department, (2) identify departments where the average salary exceeds the company-wide average, and (3) list managers whose team average salary is below their own salary.','Coding','Use window functions (ROW_NUMBER / RANK) for top-N per group. Use a subquery or CTE for company-wide average. For managers, self-join employees to get their team via dept_id.','Query 1 requires ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC) in a CTE, then filtering WHERE rn <= 3. Query 2 uses GROUP BY dept_id HAVING AVG(salary) > (SELECT AVG(salary) FROM employees). Query 3 joins departments to employees twice — once for the team avg, once for the manager''s own salary. Using CTEs for readability over nested subqueries shows SQL maturity. Mentioning that these queries would benefit from indexes on dept_id and salary is production-aware thinking.') on conflict (id) do nothing;
insert into gethired_private.categories(id,name,description,color,bg,phases) values ('c7614fd9-53ca-4eef-82fc-48c61bc09a0a','Network Engineering','OSI model, TCP/IP, routing, switching, troubleshooting','#065f46','#d1fae5','[{"id":"intro","label":"Introduction","shortLabel":"Intro","types":["Introduction"],"count":1},{"id":"situational","label":"Situational","shortLabel":"Situational","types":["Situational"],"count":1},{"id":"technical","label":"Technical","shortLabel":"Technical","types":["Technical"],"count":2},{"id":"your-questions","label":"Your Questions","shortLabel":"Q&A","types":["Candidate Questions"],"count":1}]') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('2211e5c4-8a07-423f-8c4e-17d6d9c63b64','c7614fd9-53ca-4eef-82fc-48c61bc09a0a','Explain the OSI model. Name each layer and describe what happens at that layer when a user types a URL into a browser and presses Enter.','Technical','Walk it top-down: Application → Presentation → Session → Transport → Network → Data Link → Physical.','A strong answer maps real events to each layer: Application (HTTP/HTTPS request formed), Presentation (TLS encryption, data encoding), Session (TCP session established), Transport (TCP segments with port numbers), Network (IP packets routed via DNS-resolved IP), Data Link (Ethernet frames with MAC address), Physical (bits over cable/WiFi). Mentioning DNS resolution, TCP three-way handshake, and TLS handshake within the appropriate layers demonstrates depth.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('a87804e1-ecd2-4736-88eb-cd8618944911','c7614fd9-53ca-4eef-82fc-48c61bc09a0a','Explain the difference between TCP and UDP. For each, name two real-world protocols that use it and explain why that transport choice makes sense.','Technical','Think: reliability, ordering, overhead. What matters more — correctness or speed?','TCP (connection-oriented, reliable, ordered, error-checked) is used by HTTP/HTTPS (correctness over speed) and SMTP (email must arrive intact). UDP (connectionless, lower overhead, no guaranteed delivery) is used by DNS (fast single lookups tolerate packet loss), video streaming/VoIP (latency beats occasional dropped frames). Mentioning QUIC as a modern UDP-based transport that adds reliability is a bonus point.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('e4c59d6c-dbe5-4513-8543-7b74f5a09b6d','c7614fd9-53ca-4eef-82fc-48c61bc09a0a','A user reports they cannot access any website but can ping 8.8.8.8 successfully. Walk through your troubleshooting process.','Situational','They have IP connectivity but not DNS resolution. Think about what ping uses vs. what a browser uses.','The key insight: ping to 8.8.8.8 succeeds (IP connectivity fine) but websites fail (DNS resolution broken). Next step is to test DNS specifically — ping google.com (hostname), run nslookup or dig to query the configured DNS server. Likely causes: DNS server unreachable, misconfigured DNS settings, or ISP DNS blocking. Fixes: change DNS to 8.8.8.8 or 1.1.1.1, flush DNS cache, check /etc/resolv.conf or network adapter settings.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('2f5d0751-e75e-44b9-80a7-8fac64be34cb','c7614fd9-53ca-4eef-82fc-48c61bc09a0a','Please introduce yourself, your academic background, a project you are proud of, and your interest in Network Engineering.','Introduction','Keep your introduction focused and specific.','Look for a clear background, a concrete example and motivation for this field.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('63d65a54-d5cc-44a2-8363-b569769c5b14','c7614fd9-53ca-4eef-82fc-48c61bc09a0a','Describe a difficult problem you solved in a Network Engineering context. What did you do and learn?','Situational','Use Situation, Task, Action and Result.','Look for a specific problem, personal actions, a concrete result and reflection.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('0f46a30f-f34b-4272-88fa-25cd5e86925e','c7614fd9-53ca-4eef-82fc-48c61bc09a0a','What would you like to ask about the role, team, mentoring or daily work?','Candidate Questions','Ask specific questions about the placement.','Look for curiosity and thoughtful questions about the role and learning opportunities.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('c56b8707-b7c0-45f7-808b-ec435eb0b550','c7614fd9-53ca-4eef-82fc-48c61bc09a0a','You have been assigned the network 172.16.0.0/20. You need to create 6 subnets of equal size to serve 6 departments, each requiring at least 200 usable host addresses. Show your work: (1) verify the requirement is achievable, (2) calculate the new subnet mask, (3) list all 6 subnet network addresses, broadcast addresses, and usable host ranges.','Coding','A /24 gives 254 hosts. Count available bits in the original /20 block (12 host bits). To create 6 subnets you need at least 3 subnet bits (2³=8 ≥ 6). New mask = /20+3 = /23. Verify: 2⁹-2 = 510 hosts per subnet ≥ 200.','A correct answer identifies that /23 (255.255.254.0) gives 8 possible subnets of 510 usable hosts each — satisfying both the count (≥6) and host (≥200) requirements. The 6 subnet network addresses increment by 512 (the block size): 172.16.0.0, 172.16.2.0, 172.16.4.0, 172.16.6.0, 172.16.8.0, 172.16.10.0. Each broadcast address is the last IP in its block (e.g., 172.16.1.255). Showing the calculation clearly (2^n formula, CIDR notation, binary subnet mask) demonstrates networking fundamentals beyond memorization.') on conflict (id) do nothing;
insert into gethired_private.categories(id,name,description,color,bg,phases) values ('7131be9c-e35e-422b-8b1d-0d4af5e6a0f2','Software QA & Testing','Test planning, manual & automated testing, bug lifecycle','#6d28d9','#ede9fe','[{"id":"intro","label":"Introduction","shortLabel":"Intro","types":["Introduction"],"count":1},{"id":"situational","label":"Situational","shortLabel":"Situational","types":["Situational"],"count":1},{"id":"technical","label":"Technical","shortLabel":"Technical","types":["Technical"],"count":1},{"id":"your-questions","label":"Your Questions","shortLabel":"Q&A","types":["Candidate Questions"],"count":1}]') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('79caf2b3-7c67-460c-8689-0641279af33c','7131be9c-e35e-422b-8b1d-0d4af5e6a0f2','Explain the difference between unit testing, integration testing, system testing, and end-to-end testing. How do they fit together in the testing pyramid?','Technical','Think about scope, speed, isolation, and cost. The pyramid has a reason for its shape.','A complete answer describes each level: unit (single function/class, fast, isolated, mocked dependencies), integration (two or more modules together, verifies interfaces), system (entire application in a controlled environment), E2E (simulates real user flows in a browser/device). The pyramid shape explains the ideal ratio: many fast unit tests, fewer integration tests, fewest slow E2E tests. Mentioning tools (Jest, Pytest, Selenium, Cypress, Postman) adds credibility.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('835943ed-902c-4edc-886d-d331004b27fc','7131be9c-e35e-422b-8b1d-0d4af5e6a0f2','You are handed a feature with no existing test plan and a two-day deadline. Walk through how you would create a test plan and prioritize what to test.','Situational','Think: requirements → risk → test cases → priority → execution order.','Strong answers start by understanding requirements and acceptance criteria, identify the highest-risk areas (new code, third-party integrations, payment flows), write test cases covering happy paths first then edge cases, and prioritize by business impact. Mentioning risk-based testing, smoke tests vs. regression tests, and what to explicitly descope given time constraints shows QA maturity. Communicating coverage decisions to the team is also key.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('7815ae2f-73df-4319-8299-57c4a6bbe5c8','7131be9c-e35e-422b-8b1d-0d4af5e6a0f2','You discover a critical bug in production the day before a major release. You reported it two days ago but it was dismissed. How do you handle this?','Situational','Balance professionalism, data-driven escalation, and the business vs. quality trade-off.','Excellent answers document the bug thoroughly (steps to reproduce, severity, business impact, affected users), escalate with data rather than emotion, and present options: delay release, ship with a known workaround, or accept the risk with a rollback plan. Showing that you track bugs systematically, communicate proactively, and respect the final decision while ensuring it is an informed one demonstrates professional QA judgment — not just technical skill.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('5baf6857-47f7-4bf8-8634-770ca9ac284f','7131be9c-e35e-422b-8b1d-0d4af5e6a0f2','Please introduce yourself, your academic background, a project you are proud of, and your interest in Software QA & Testing.','Introduction','Keep your introduction focused and specific.','Look for a clear background, a concrete example and motivation for this field.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('c77dde0b-2346-4cfd-8cc2-9589937826b6','7131be9c-e35e-422b-8b1d-0d4af5e6a0f2','Describe a difficult problem you solved in a Software QA & Testing context. What did you do and learn?','Situational','Use Situation, Task, Action and Result.','Look for a specific problem, personal actions, a concrete result and reflection.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('ac25d91f-105c-4210-8b3d-2cbfdcb42dda','7131be9c-e35e-422b-8b1d-0d4af5e6a0f2','What would you like to ask about the role, team, mentoring or daily work?','Candidate Questions','Ask specific questions about the placement.','Look for curiosity and thoughtful questions about the role and learning opportunities.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('750b0f78-4153-4251-8eed-acba83680288','7131be9c-e35e-422b-8b1d-0d4af5e6a0f2','Write a comprehensive set of test cases for a login form with these requirements: (1) email must be valid format, (2) password must be at least 8 characters, (3) account locks after 5 failed attempts for 30 minutes, (4) successful login redirects to dashboard, (5) ''Forgot Password'' link is present. Include positive, negative, and edge cases. Use a clear format: Test ID | Scenario | Input | Expected Result | Priority.','Coding','Cover happy path, boundary values (7 chars vs 8 chars), invalid formats, SQL injection attempt, empty fields, case sensitivity, account lockout (4 fails vs 5th fail vs 6th attempt during lockout), and the forgot password link.','A thorough test suite covers: TC01 valid login (P1), TC02 invalid email format (P1), TC03 password exactly 7 chars (P1), TC04 password exactly 8 chars (P1), TC05 empty email (P1), TC06 empty password (P1), TC07 SQL injection in email field (P1 — security), TC08 4th failed attempt — no lockout yet (P2), TC09 5th failed attempt — triggers lockout (P1), TC10 attempt during lockout period (P1), TC11 lockout expires after 30 min (P2), TC12 forgot password link visible and navigates (P2), TC13 case-insensitive email (P3). Missing security test cases or lockout boundary tests are the most common gaps.') on conflict (id) do nothing;
insert into gethired_private.categories(id,name,description,color,bg,phases) values ('04d63b74-a42b-4f38-8e64-84d391e2c1a6','Game Development','Unity, Unreal Engine, C#, C++, gameplay physics, shaders, game loops','#ea580c','#ffedd5','[{"id":"intro","label":"Introduction","shortLabel":"Intro","types":["Introduction"],"count":1},{"id":"situational","label":"Situational","shortLabel":"Situational","types":["Situational"],"count":1},{"id":"technical","label":"Technical","shortLabel":"Technical","types":["Technical"],"count":2},{"id":"coding","label":"Practical Challenge","shortLabel":"Practical","types":["Coding"],"count":1},{"id":"your-questions","label":"Your Questions","shortLabel":"Q&A","types":["Candidate Questions"],"count":1}]') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('1fb66c51-8a23-4d6a-81c2-5a67ba8296fc','04d63b74-a42b-4f38-8e64-84d391e2c1a6','Explain the difference between Update() and FixedUpdate() in a game engine like Unity. Why is frame-rate independence critical in game physics, and what happens if you move physics-driven objects inside Update()?','Technical','Think about variable frame times (Time.deltaTime) vs. fixed physics tick intervals (Time.fixedDeltaTime).','A strong answer explains that Update() runs once per rendered frame (variable rate depending on hardware workload), whereas FixedUpdate() runs on a reliable fixed physics timer (default 50Hz in Unity). Moving physics or applying forces inside Update() causes jitter, clipping, or tunneling because delta time fluctuates between frames. Calculating physics exclusively in FixedUpdate() guarantees deterministic, stable simulation across high-end and low-end target devices.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('994a6960-bf02-4f7e-8039-25dbe4f86c72','04d63b74-a42b-4f38-8e64-84d391e2c1a6','What is Object Pooling in game development? Walk through why frequent instantiation and destruction of game objects causes performance stutters (garbage collection spikes), and how an object pool resolves this.','Technical','Focus on heap allocation, Garbage Collector pauses, active/inactive states, and recycling.','An excellent explanation describes how Instantiate() allocates heap memory and Destroy() leaves unreferenced memory, triggering the C# Garbage Collector (GC). When GC kicks in, it halts execution, causing noticeable frame drops and micro-stutters. Object pooling pre-allocates a fixed pool of objects (e.g., bullets, enemies, particles) at initialization, activates them on demand, and deactivates/recycles them back to the pool instead of destroying them, keeping frame rates buttery smooth.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('53a07d2a-10cc-44ea-8d1c-a9249519b54d','04d63b74-a42b-4f38-8e64-84d391e2c1a6','Describe a challenging game bug you encountered (e.g., physics glitch, memory leak, collision tunneling, animation desync). How did you profile, isolate, and fix it under a deadline or game jam setting?','Behavioral','Use STAR. Discuss profiling tools (Unity Profiler, Unreal Insights), repro steps, and performance impact.','Strong answers describe systematic problem-solving: capturing repro steps, using engine profilers (profiling CPU spikes, memory allocations, draw calls), isolating the subsystem, and applying a clean architectural fix rather than a quick hack. Mentioning playtesting feedback or deadline prioritization highlights real-world game development team readiness.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('372a153d-2928-4b8a-876e-72cc7c31629f','04d63b74-a42b-4f38-8e64-84d391e2c1a6','Please introduce yourself, your academic background, a project you are proud of, and your interest in Game Development.','Introduction','Keep your introduction focused and specific.','Look for a clear background, a concrete example and motivation for this field.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('6267b6c8-80f3-403c-8b3e-4e5df35d7510','04d63b74-a42b-4f38-8e64-84d391e2c1a6','Describe a difficult problem you solved in a Game Development context. What did you do and learn?','Situational','Use Situation, Task, Action and Result.','Look for a specific problem, personal actions, a concrete result and reflection.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('61bbba68-760f-4214-83d2-2cc3d74061dc','04d63b74-a42b-4f38-8e64-84d391e2c1a6','What would you like to ask about the role, team, mentoring or daily work?','Candidate Questions','Ask specific questions about the placement.','Look for curiosity and thoughtful questions about the role and learning opportunities.') on conflict (id) do nothing;
insert into gethired_private.questions(id,category_id,question,type,hint,feedback) values ('02a82af3-ef99-46b8-88b5-d4dfcbb2859d','04d63b74-a42b-4f38-8e64-84d391e2c1a6','Implement a generic ObjectPool class in C# (or pseudo-code) for reusable GameObjects. Include: (1) an initialization method that pre-warms the pool with N instances, (2) a Get() method that retrieves an inactive object (or instantiates a new one if empty), and (3) a ReturnToPool() method that resets the object''s state and returns it to the pool.','Coding','Use a Queue<T> or List<T> for storing inactive pooled items. Ensure instantiated objects start inactive and are set active upon retrieval.','A complete implementation uses a Queue<T> for O(1) dequeue and enqueue operations, pre-warms the pool in the constructor/init, sets gameObject.SetActive(true) when retrieved, and SetActive(false) with a state reset interface (like IPoolable.OnSpawn/OnDespawn) when returned. Bonus points for handling pool expansion with a maximum capacity guard, or thread-safety considerations.') on conflict (id) do nothing;
